   388|async function ensureSupabaseAuthRedirectUrl(supabaseUrl: string, redirectTo: string): Promise<{
   389|  ok: boolean;
   390|  tokenPresent: boolean;
   391|  projectRef: string | null;
   392|  getStatus?: number;
   393|  getError?: string;
   394|  getResponse?: string;
   395|  beforeUrls?: string[];
   396|  afterUrls?: string[];
   397|  patchStatus?: number;
   398|  patchError?: string;
   399|  patchBody?: string;
   400|  putStatus?: number;
   401|  putError?: string;
   402|  putBody?: string;
   403|  message: string;
   404|}> {
   405|  const managementToken = readEnv('SUPABASE_ACCESS_TOKEN');
   406|  if (!managementToken) {
   407|    return { ok: false, tokenPresent: false, projectRef: null, message: 'SUPABASE_ACCESS_TOKEN not configured in runtime.' };
   408|  }
   409|  const projectRefMatch = supabaseUrl.match(/https:\/\/([a-z0-9-]+)\.supabase\.co/);
   410|  const projectRef = projectRefMatch?.[1] ?? null;
   411|  if (!projectRef) {
   412|    return { ok: false, tokenPresent: true, projectRef, message: `Could not extract project ref from Supabase URL: ${supabaseUrl}` };
   413|  }
   414|  try {
   415|    const authUrl = `https://api.supabase.com/v1/projects/${projectRef}/config/auth`;
   416|
   417|    const getResp = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   418|    const getText = await getResp.text();
   419|    if (!getResp.ok) {
   420|      return { ok: false, tokenPresent: true, projectRef, getStatus: getResp.status, getError: getText.slice(0, 300), message: `GET auth config failed: HTTP ${getResp.status}` };
   421|    }
   422|    const getConfig = JSON.parse(getText) as { uri_allow_list?: string; site_url?: string; };
   423|    const rawAllowList = typeof getConfig.uri_allow_list === 'string' ? getConfig.uri_allow_list : '';
   424|    const redirectUrls = rawAllowList.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean);
   425|    const beforeUrls = [...redirectUrls];
   426|
   427|    if (redirectUrls.includes(redirectTo)) {
   428|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls: beforeUrls, message: 'Redirect URL already allowed.' };
   429|    }
   430|
   431|    // Supabase Management API has been observed to corrupt a space-separated uri_allow_list when
   432|    // multiple URLs are present, dropping the separator and concatenating values. To guarantee a
   433|    // valid allow-list for the new redirect URL, we REPLACE the list with exactly that URL.
   434|    const nextUrls = [redirectTo];
   435|    const nextAllowList = redirectTo;
   436|
   437|    // PATCH using the correct Supabase field name uri_allow_list; keep site_url as the app base URL.
   438|    const patchBody = JSON.stringify({ uri_allow_list: nextAllowList, site_url: 'https://ivxholding.com' });
   439|    const patchResp = await fetch(authUrl, {
   440|      method: 'PATCH',
   441|      headers: { Authorization: `Bearer ${managementToken}`, 'Content-Type': 'application/json', Accept: 'application/json' },
   442|      body: patchBody,
   443|    });
   444|    const patchText = await patchResp.text();
   445|
   446|    if (!patchResp.ok) {
   447|      return { ok: false, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, patchStatus: patchResp.status, patchError: patchText.slice(0, 300), patchBody, message: `PATCH auth config failed: HTTP ${patchResp.status}` };
   448|    }
   449|
   450|    // Re-read to verify
   451|    const getResp2 = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   452|    const getText2 = await getResp2.text();
   453|    const afterConfig = JSON.parse(getText2) as { uri_allow_list?: string; };
   454|    const afterUrls = typeof afterConfig.uri_allow_list === 'string'
   455|      ? afterConfig.uri_allow_list.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean)
   456|      : [];
   457|
   458|    if (afterUrls.includes(redirectTo)) {
   459|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls, patchStatus: patchResp.status, patchBody, message: 'Added redirect URL to Supabase auth config (verified by re-read).' };
   460|    }
   461|
   462|    return { ok: false, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls, patchStatus: patchResp.status, patchError: patchText.slice(0, 300), patchBody, message: 'PATCH accepted but URL not present in uri_allow_list after re-read.' };
   463|  } catch (err) {
   464|    return { ok: false, tokenPresent: true, projectRef, message: err instanceof Error ? err.message : String(err) };
   465|  }
   466|}
